SELECT DISTINCT q.id as question_id, q.name as question_name, q.question_type_id as question_type_id, q.difficulty, q.points, kp.point_id as point_id, kp.point_name as point_name, f.field_id as field_id, f.field_name as field_name FROM et_question q LEFT JOIN et_question_2_point qp ON q.id = qp.question_id LEFT JOIN et_knowledge_point kp ON qp.point_id = kp.point_id LEFT JOIN et_field f ON kp.field_id = f.field_id
AND q.name LIKE CONCAT('%', #{questionName}, '%')
AND q.question_type_id = #{questionTypeId}
AND kp.point_id = #{pointId}
AND f.field_id = #{fieldId}
ORDER BY q.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT q.id)
FROM et_question q
LEFT JOIN et_question_2_point qp ON q.id = qp.question_id
LEFT JOIN et_knowledge_point kp ON qp.point_id = kp.point_id
LEFT JOIN et_field f ON kp.field_id = f.field_id


        AND q.name LIKE CONCAT('%', #{questionName}, '%')


        AND q.question_type_id = #{questionTypeId}


        AND kp.point_id = #{pointId}


        AND f.field_id = #{fieldId}
